推荐口述：“我把 OTA 分成 IDLE → RECEIVING → PROGRAMMING → VERIFYING → PENDING_BOOT → CONFIRMED/ROLLBACK。YMODEM 层对每个包做序号和 CRC16，写 Flash 时只操作非活动区；接收结束后再按镜像头中的长度计算 CRC32，并校验版本、地址范围和元数据。Bootloader 启动时先验证目标区，验证通过进入试运行，应用完成时钟、传感器、存储和通信自检后写 CONFIRMED；如果校验失败、看门狗复位或连续多次没有确认，就清除 pending 标志并回退旧区。”
元数据要做双备份和幂等提交，掉电发生在任意一步都能从旧记录恢复。CRC 只能发现传输/存储错误，不能防篡改；量产场景还要加签名验证和密钥保护。
typedef enum { OTA_IDLE, OTA_RX, OTA_VERIFY, OTA_TRIAL, OTA_CONFIRMED, OTA_ROLLBACK } ota_state_t;
typedef struct { uint32_t magic, version, size, crc32; uint8_t target_bank, boot_attempts, confirmed; } ota_meta_t;

bool ota_finalize(const image_t *img, ota_meta_t *m) {
    if (!range_ok(img->addr, img->size) || crc32_flash(img->addr, img->size) != img->crc32) return false;
    m->target_bank = inactive_bank(); m->boot_attempts = 0; m->confirmed = 0;
    return meta_commit_atomic(m);
}

void boot_decide(ota_meta_t *m) {
    if (m->confirmed) return;
    if (m->boot_attempts < 3 && image_valid(m->target_bank)) {
        m->boot_attempts++; meta_commit_atomic(m); boot(m->target_bank);
    } else { rollback_to_active_bank(m); }
}

open 得到 fd，内核创建或引用 file 对象，随后 read/write/ioctl/poll 映射到文件系统或驱动回调，close 释放引用。0/1/2 默认是 stdin/stdout/stderr。代码必须处理 errno、短读写、EINTR、非阻塞 EAGAIN，并设置 O_CLOEXEC 防止 exec 后泄漏。
int fd = open("/dev/my_led", O_WRONLY | O_CLOEXEC);
if (fd < 0) { perror("open"); return 1; }
char value = '1';
if (write(fd, &value, 1) != 1) perror("write");
if (close(fd) < 0) perror("close");

fork 返回两次：父进程拿到子 PID，子进程得到 0，页表采用写时复制。子进程关闭无关 fd 后调用 execve/execvp，exec 成功不返回。父进程必须 waitpid，否则子进程退出后留下僵尸。
pid_t pid = fork();
if (pid == 0) { execl("/bin/echo", "echo", "child", NULL); _exit(127); }
if (pid > 0) { int status; waitpid(pid, &status, 0); }
实验中故意不 wait，用 ps -o pid,ppid,state,cmd 观察 Z，再用 SIGCHLD + 非阻塞 waitpid 循环修复。

生产者/消费者队列由 mutex 保护，生产者入队后 signal，消费者用 pthread_cond_wait 原子释放锁并睡眠，被唤醒后重新抢锁并检查条件。必须用 while 防止虚假唤醒和多个消费者竞争。持锁期间不做阻塞 I/O。
pthread_mutex_lock(&lock);
while (queue_empty() && !stopping)
    pthread_cond_wait(&not_empty, &lock);
if (!queue_empty()) item = pop_item();
pthread_mutex_unlock(&lock);

所有数据 fd 设置 O_NONBLOCK 并注册到 epoll。收到可读事件后循环 read 到 EAGAIN；timerfd 做周期统计，eventfd 消费队列，signalfd 做有序退出。水平触发易入门，但仍要 drain 避免重复唤醒。主循环只做轻量解析，SD 写入和网络阻塞任务通过有界队列下放。
for (;;) {
    int n = epoll_wait(epfd, events, MAX_EVENTS, -1);
    for (int i = 0; i < n; ++i) dispatch(events[i].data.fd);
}

最小模块包含 module_init、module_exit、MODULE_LICENSE。用目标内核 build 目录编译，板端 insmod、lsmod、dmesg -w、rmmod 验证。insmod 直接插入 .ko，不自动处理依赖；modprobe 根据 modules.dep 加载依赖。
static int __init demo_init(void) { pr_info("demo init\n"); return 0; }
static void __exit demo_exit(void) { pr_info("demo exit\n"); }
module_init(demo_init);
module_exit(demo_exit);
MODULE_LICENSE("GPL");

顺序是 alloc_chrdev_region → cdev_init/cdev_add → class_create → device_create；退出严格反向。open 建立上下文，read/write 处理数据，unlocked_ioctl 传结构化命令，release 释放每次打开状态。先用内核环形缓冲验证框架，再接 GPIO，能把框架错误与硬件问题分离。
static const struct file_operations fops = {
    .owner = THIS_MODULE, .open = demo_open, .read = demo_read,
    .write = demo_write, .unlocked_ioctl = demo_ioctl,
    .release = demo_release,
};

用户指针可能无效或被并发修改，不能直接解引用。copy_from_user/copy_to_user 返回未复制字节数，非零转为 -EFAULT。ioctl 用 _IO/_IOR/_IOW/_IOWR，结构体采用固定宽度字段和 version/size，检查范围和权限。
struct demo_cfg { __u32 version; __u32 period_ms; __u8 enable; };
if (copy_from_user(&cfg, argp, sizeof(cfg))) return -EFAULT;
if (cfg.period_ms == 0) return -EINVAL;
用 NULL、错误长度、超大参数做错误注入，驱动应返回错误而不是 Oops。

原则：把占用空间大的成员放前面、小的放后面，减少内部填充。
// 差：24字节（char后7字节padding + int在中间）
struct Bad  { char a; double b; int c; };
// 好：16字节（double占8+int占4+char占1+尾部3字节padding）
struct Good { double b; int c; char a; };
也按"对齐要求从大到小"排序。在通信协议帧中如果必须按协议顺序排列，则需要用#pragma pack(1)或__attribute__((packed))紧凑排列。注意pack后可能产生非对齐访问，部分架构（如Cortex-M0）不支持。
